OPP-C05.raw:
{
  "hypothesis": "We believe that account-level sync status and a refresh action in Integrations for SMB workspace members using CRM will help them diagnose missing accounts because the integration-wide green state may not reveal account-level issues.",
  "intervention": "Prototype an account-level sync status beside CRM accounts in the project view, with a refresh action for accounts that are missing. Use the prototype in a scenario where an account is absent from that view.",
  "target_audience": "SMB workspace members using the CRM integration, including members who are not workspace owners.",
  "primary_metric": {
    "name": "Successful diagnosis and recovery-path identification",
    "definition": "Whether a participant correctly interprets the account's sync status and identifies an appropriate next step during the missing-account scenario."
  },
  "guardrail_metrics": [
    {
      "name": "Misleading confidence",
      "why": "Check whether participants incorrectly conclude that an absent account is syncing successfully."
    },
    {
      "name": "Integration health comprehension",
      "why": "Check that account-level status does not confuse participants about the overall integration state."
    }
  ],
  "experiment_design": {
    "type": "Usability study",
    "description": "Give SMB CRM integration users a prototype and ask them to investigate an account that is missing from the project view. Observe whether they understand its status and find the refresh action, and ask what they believe the status means."
  },
  "risks": [
    "A prototype may not reveal how users behave when real sync delays or failures occur.",
    "Participants may interpret a refresh action as a guaranteed fix."
  ],
  "assumptions_to_validate": [
    "The CRM integration has a meaningful account-level sync state that can be shown to users.",
    "SMB workspace members can access the relevant account information and refresh action.",
    "Users can distinguish an account-level issue from an overall integration issue."
  ]
}
